-- US admission requirements, retry of 16 schools that failed in step186 (checked 13 Nov 2026). Needs step181.
update schools set admission_info = $q${"ug": "Applicants with 12 years of schooling may be admitted if their school record shows above-average results. Courses should cover your native language, English, math, science, social science and humanities, and your school must be recognized by your country's ministry of education. No minimum GPA is listed.", "pg": "A conferred bachelor's degree, or a 3.0 GPA on the last 60 credit hours if the degree is not finished yet. You must be admitted to the Graduate School and also to a specific program.", "english": "Undergraduate and graduate minimums: TOEFL iBT 79, IELTS Academic 6.5, Duolingo 110 (graduate Duolingo not accepted for Walton College). Undergraduate also accepts PTE-A 58, SAT reading and writing 500 or ACT English 19. Native English speakers can be exempt; graduate applicants with WASSCE at grade B or better may be exempt with Graduate Dean approval.", "how_to_apply": "Fill in the online application, then use the Applicant Portal to pay the fee and upload your documents. Undergraduate review takes about 2 to 3 weeks after your file is complete. Graduate applicants should also check their department for extra steps.", "deadlines": "No undergraduate deadline is listed on the page. Graduate deadlines are set by each program. A scholarship deadline exists but the date is not given.", "application_fee": "Undergraduate USD 65. Graduate USD 75. Both are not refundable.", "documents": "Undergraduate: school transcripts and certificate with stamped English translations, passport name page, SAT or ACT scores if you want scholarship consideration, and a financial form with bank proof for the I-20. Graduate: unofficial transcripts, English test proof, GRE or similar if your program asks, and program papers such as a statement or CV.", "fees_link": "https://international-admissions.uark.edu/undergraduate-studies/new-freshmen.php", "sources": ["https://international-admissions.uark.edu/undergraduate-studies/new-freshmen.php", "https://international-admissions.uark.edu/undergraduate-studies/english-proficiency.php", "https://international-admissions.uark.edu/graduate-studies/english-proficiency.php", "https://international-admissions.uark.edu/graduate-studies/applying/degree-seeking.php", "https://international-admissions.uark.edu/undergraduate-studies/admissions-requirements/"]}$q$::jsonb, admission_link = $q$https://international-admissions.uark.edu/undergraduate-studies/new-freshmen.php$q$, admission_checked = '2026-11-13' where id = 'ffe4a569-9e34-4346-8c67-7b69afb46b00' and country = 'United States';
update schools set admission_info = $q${"ug": "Finish secondary school with a certificate that allows university entry in your country. IGCSE or O-Levels alone are not enough; the page points to a two-year A-level program with at least three exams, the IB Diploma, or a similar course. Results of final exams such as A-levels are sent after admission.", "english": "Any one of: TOEFL 90, IELTS 6.5, Duolingo 115, SAT Writing and Language 31, ACT English 24, AP English 3 or higher, IB English at the listed scores, or 3 or more years of instruction fully in English. Transfer applicants do not need an English exam.", "how_to_apply": "Apply through ApplyUC. List your school history as it appears on your records and do not convert your grades. Berkeley does not do interviews. After admission you complete the Non-immigrant Information Form and show a sponsor's guarantee for first-year funds so the International Office can issue your visa document.", "deadlines": "English proficiency must be met by January 31. Optional InitialView materials are due November 30. Exam scores must be valid for two years from enrollment.", "application_fee": "Not confirmed on the page.", "documents": "English test score (official TOEFL and SAT scores sent through ETS code 4833), your school record details in ApplyUC, and after admission the Non-immigrant Information Form and financial guarantee.", "fees_link": "https://admissions.berkeley.edu/requirements", "sources": ["https://admissions.berkeley.edu/requirements"]}$q$::jsonb, admission_link = $q$https://admissions.berkeley.edu/requirements$q$, admission_checked = '2026-11-13' where id = 'fd7f4821-0f58-4dd4-ba71-290386e62e75' and country = 'United States';
update schools set admission_info = $q${"ug": "Secondary certificate equal to a US high school diploma with required subjects completed at a minimum 3.4 average. Subjects include four years of your language of instruction, three years of math, science, a second language and one year of arts. British-style systems need at least 5 O-Level or GCSE passes and 3 A-Level passes at C or better. No letters of recommendation are accepted.", "english": "Needed if your school language was not English and you had less than 3 years of English instruction. Accepted: IELTS 6.5, TOEFL iBT 4.5 (new scale from January 2026; 80 before), Duolingo 115, SAT reading and writing 680 or ACT English 24.", "how_to_apply": "Apply yourself through the UC Application and choose UC Irvine. UCI does not work with agents and using one can lead to withdrawal of your application. List all your school history and exam scores and do not convert grades.", "deadlines": "UC application opens August 1 and is submitted October 1 to November 30. Final transcripts are due July 1 if admitted.", "application_fee": "USD 95 for international applicants, not refundable.", "documents": "No official transcripts or recommendation letters at application. Official transcripts and official English scores are needed after you are admitted. Use your full name as on your passport.", "fees_link": "https://admissions.uci.edu/apply/how-to-apply/index.php", "sources": ["https://admissions.uci.edu/apply/international-students.php", "https://admissions.uci.edu/apply/how-to-apply/index.php"]}$q$::jsonb, admission_link = $q$https://admissions.uci.edu/apply/how-to-apply/index.php$q$, admission_checked = '2026-11-13' where id = 'bba8a322-5fc6-49c4-9482-a629c447e0ce' and country = 'United States';
update schools set admission_info = $q${"ug": "Freshmen need a secondary school GPA of about 3.00 on a 4.00 scale or higher, and math and science grades are also reviewed. Transfer students need at least 24 semester credits and a 2.50 GPA.", "pg": "Apply through the Graduate Division and your program. Many programs ask for the GRE, so check your program.", "english": "TOEFL iBT 61 for admission with English Language Institute classes, or 100 for no classes; IELTS 5.5 or 7.0; Duolingo 90 or 135; PTE-A 44 or 68. For graduate applicants, accepted tests are TOEFL iBT, TOEFL Essentials, IELTS, Duolingo and Cambridge C1 or C2; the graduate minimum scores are on a separate page that was not confirmed.", "how_to_apply": "Apply online through the Hawaii Central Application. Official records must be sent directly by your school or ministry of education, not by you. Send materials to manoa.admissions@hawaii.edu or by mail to the Office of Admissions in Honolulu.", "deadlines": "Undergraduate final deadlines are April 1 for fall and October 1 for spring. Some programs such as nursing, social work and education have earlier dates. Graduate deadlines are not confirmed on the pages read. Allow 3 months before the semester starts for visa papers.", "application_fee": "Undergraduate USD 70, not refundable. Graduate fee not confirmed.", "documents": "Official school transcripts with grading explanation and class rank, exam certificates from the exam board, certified English translations, and the Supplementary Information Form for Foreign Applicants (Section C needs bank statements for the F-1 visa). Graduate: passport copy, transcripts from every school attended and the Confidential Financial Statement.", "fees_link": "https://manoa.hawaii.edu/admissions/international.html", "sources": ["https://manoa.hawaii.edu/admissions/international.html", "https://manoa.hawaii.edu/graduate/admissions-requirements/", "https://manoa.hawaii.edu/graduate/standardized-exams/"]}$q$::jsonb, admission_link = $q$https://manoa.hawaii.edu/admissions/international.html$q$, admission_checked = '2026-11-13' where id = '9eee5548-509c-4fd9-87de-a812d06d0bbc' and country = 'United States';
update schools set admission_info = $q${"ug": "First-year applicants need at least a 2.5 GPA on a 4.0 scale from secondary school and must meet university entry rules in their home country. Some departments set higher limits.", "pg": "A bachelor's degree from an accredited school equal to a US four-year degree (120 semester credits), with official records from all schools attended.", "english": "Undergraduate: an official TOEFL or equal score is needed; the minimum is not listed on the page. Graduate: TOEFL 79 (4.5 on the new scale from January 21, 2026), IELTS 6.5, Duolingo 115, PTE Academic 58, or passing the university's English program. Scores must be within two years.", "how_to_apply": "Submit the international application and fee, then all documents including financial papers. Admission is rolling. Send a complete application at least 3 months before your start term.", "deadlines": "Rolling admission with no hard undergraduate deadline. Graduate deadlines are on a separate page that was not confirmed.", "application_fee": "Undergraduate USD 50, not refundable. Graduate fee not confirmed.", "documents": "Undergraduate: application, official school transcripts, English score, certified translations, Certificate of Financial Responsibility, bank letter or statement, and passport copy. Graduate: official transcripts from all schools; a course-by-course evaluation (WES preferred) may be asked for; proof of funds before the I-20.", "fees_link": "https://uidaho.edu/admissions/international/admissions-requirements/undergraduate-admission", "sources": ["https://sitecore03a.its.uidaho.edu/admissions/international/admissions-requirements/undergraduate-admission", "https://uidaho.edu/admissions/graduate/international"]}$q$::jsonb, admission_link = $q$https://uidaho.edu/admissions/international/admissions-requirements/undergraduate-admission$q$, admission_checked = '2026-11-13' where id = '74eb1124-6aed-4d21-9ccf-d904c17e5fc5' and country = 'United States';
update schools set admission_info = $q${"ug": "A minimum 2.5 GPA on a 4.0 scale for all previous coursework. You also need proof of secondary school graduation for your country.", "pg": "Scanned official transcripts and a degree certificate or diploma for degrees earned outside the US. Proof of finances is not needed to be considered, only after admission.", "english": "Accepted tests are TOEFL, IELTS and Duolingo, sent from the testing agency and less than 2 years old. The score cutoffs are not on the pages read; applicants below the standard can be admitted to take English courses at the Applied English Center. Graduate non-native speakers must also prove English; the scores are on a separate page.", "how_to_apply": "Use the Apply Now link at world.ku.edu/apply. Students who do not meet full English level may be admitted as degree-seeking and take Applied English Center courses.", "deadlines": "For students outside the US: November 15 for spring, and May 1 for fall (also the fall scholarship deadline). Graduate deadlines not confirmed.", "application_fee": "Undergraduate USD 90, no waiver. Graduate fee not confirmed.", "documents": "English test scores, proof of high school graduation, school records (unofficial at application, official before enrolling), statement explaining any gap of more than 3 months, and a third-party release if an agent helps. Graduate: transcripts and degree certificate with English translations.", "fees_link": "https://world.ku.edu/apply", "sources": ["https://world.ku.edu/apply", "https://services.ku.edu/TDClient/818/Portal/KB/ArticleDet?ID=21154", "https://gradapply.ku.edu/International-requirements"]}$q$::jsonb, admission_link = $q$https://world.ku.edu/apply$q$, admission_checked = '2026-11-13' where id = 'cd0ef62a-d5eb-4c04-bf95-8e0b8346c787' and country = 'United States';
update schools set admission_info = $q${"ug": "Freshmen need to graduate from an accredited secondary school with at least a 2.5 GPA on a 4.0 scale. Transfer students need a 2.0 college GPA, plus a 2.5 school GPA if under 24 college credits. Engineering and Business transfers should have 2.5 and health professions 3.0.", "english": "English proficiency is not required for most undergraduate programs; admission is based on academic record. The College of Architecture, Planning and Design requires it. Test scores are not listed on the pages read.", "how_to_apply": "Complete the online application (about 30 minutes) or apply through Common App. It also triggers an automatic review for general university scholarships. Then pay the fee, send transcripts, email a passport PDF, and send the Affidavit of Financial Support with a bank statement to get your I-20. Review takes about two weeks.", "deadlines": "Priority dates: December 1 for spring and May 1 for fall.", "application_fee": "USD 80, not refundable. Can be paid by card, by Flywire in local currency, or by money order.", "documents": "High school and any college transcripts, passport copy as PDF, and the Affidavit of Financial Support with bank statement.", "fees_link": "https://www.k-state.edu/admissions/undergrad/manhattan/apply/international/guide.html", "sources": ["https://www.k-state.edu/admissions/undergrad/manhattan/apply/international/requirements.html", "https://www.k-state.edu/admissions/undergrad/manhattan/apply/international/guide.html"]}$q$::jsonb, admission_link = $q$https://www.k-state.edu/admissions/undergrad/manhattan/apply/international/guide.html$q$, admission_checked = '2026-11-13' where id = 'c86f464d-4c7d-4d44-87b5-9ada1c612f63' and country = 'United States';
update schools set admission_info = $q${"ug": "Finish secondary school in a pre-university course, shown by records from 9th grade on. Students who finished school 2 or more years ago must send external exam results such as WASSCE. SAT and ACT are not required.", "pg": "A US-equal bachelor's degree with transcript, plus any department papers. An admission test such as GRE or GMAT if your department requires it.", "english": "Undergraduate: English ability to handle a full course; the score table is on a page that was not confirmed. SAT or ACT can be used to meet it. Graduate: TOEFL iBT 65 to 79, IELTS 5.5 to 6.0 or Duolingo 90 to 109 gives conditional admission with English classes; below those scores needs the English Language Center first. The score for regular admission was not confirmed.", "how_to_apply": "Apply online, then complete the Financial Support Form on your Application Status page. Graduate applicants apply through the Graduate School and the fee must be paid before processing. Contact goglobal@MiamiOH.edu for undergraduate help.", "deadlines": "Not confirmed on the pages read.", "application_fee": "Not confirmed. Graduate fee is required but the amount is not stated.", "documents": "Final official school transcripts and graduation proof, external exam results if needed, bank statement dated within 1 year, passport copy, and Form I-20 for the visa. Graduate: transcript, certified translations, medical history form, and department papers.", "fees_link": "https://bulletin.miamioh.edu/admission-undergraduate-students/", "sources": ["https://bulletin.miamioh.edu/admission-undergraduate-students/", "https://bulletin.miamioh.edu/admission-graduate-students", "https://www.miamioh.edu/policy-library/students/undergraduate/academic-regulations/undergraduate-admission.html"]}$q$::jsonb, admission_link = $q$https://bulletin.miamioh.edu/admission-undergraduate-students/$q$, admission_checked = '2026-11-13' where id = 'f9a804f8-7a24-4356-8ea2-fa5d88c60e92' and country = 'United States';
update schools set admission_info = $q${"ug": "You must have finished secondary school and not yet enrolled at a college. UCLA does not admit applicants who already hold a bachelor's degree. Send records from each secondary school showing subjects and grades, plus any national or government certificates.", "pg": "Applicants with a bachelor's degree from a US university, or from a country where English is the only language of instruction, are exempt from English tests. Departments may set higher requirements, so check each program page.", "english": "Undergraduate: no proof needed if all secondary school was in English. If not, and you have under 3 years of English instruction, send TOEFL, IELTS or Duolingo. Competitive scores are TOEFL above 100 (old scale), IELTS 7.5 or higher, Duolingo 135 or higher. Graduate: TOEFL iBT 87 or IELTS Academic 7.0 minimum.", "how_to_apply": "Undergraduates apply through the UC Application. Test scores are self-reported on the application by January. If admitted, you receive a packet that explains how to send original documents with English translations.", "documents": "Secondary school records with subjects and grades, national or government certificates, and English test scores if needed. Report external exam results in the International External Exams section of the UC Application.", "fees_link": "https://admission.ucla.edu/apply/international-applicants", "sources": ["https://admission.ucla.edu/apply/international-applicants", "https://admission.ucla.edu/international", "https://grad.ucla.edu/admissions/english-requirements/"]}$q$::jsonb, admission_link = $q$https://admission.ucla.edu/apply/international-applicants$q$, admission_checked = '2026-11-13' where id = 'fdbbceec-ad61-4eea-a3f2-f185f26da921' and country = 'United States';
update schools set admission_info = $q${"ug": "You need the equivalent of a US high school diploma. Applicants with the West African School Certificate or a similar exam must show at least 5 passes at grade C or higher. Send transcripts covering the final three years of secondary school.", "pg": "UNT says departments may ask for extra items such as portfolios, auditions or references. Graduate applicants use the separate graduate application.", "english": "Accepted: TOEFL iBT 79 (tests before 21 Jan 2026), IELTS 6.0, PTE 53, Duolingo 100. WAEC/WASSCE and NECO English at B2 or higher is also accepted. Scores must be under 2 years old.", "how_to_apply": "Apply with ApplyTexas or the Common Application for undergraduate, or the graduate application for graduate study. Pay the fee, send official documents, and track your status in myUNT. Decisions are made on a rolling basis.", "deadlines": "International freshman: Fall July 15, Spring November 15, Summer (3-week session) April 15.", "application_fee": "$85 for undergraduates and $75 for graduate applicants. The fee is not refunded. International applicants who are not Texas residents cannot get a fee waiver.", "documents": "Official transcripts, diplomas and certificates sent directly from the school or exam board, with English translations. Yearly marksheets, not a combined one. UNT does not accept notarized or copied transcripts.", "fees_link": "https://unt.edu/admissions/freshman/deadlines-fees.html", "sources": ["https://www.unt.edu/admissions/international/how-to-apply.html", "https://unt.edu/admissions/international/required-academic-credentials.html", "https://www.unt.edu/admissions/international/english-language-requirements.html", "https://unt.edu/admissions/freshman/deadlines-fees.html"]}$q$::jsonb, admission_link = $q$https://unt.edu/admissions/international/required-academic-credentials.html$q$, admission_checked = '2026-11-13' where id = 'f7dbb119-ea20-4d4e-8da4-fc102cbbaddb' and country = 'United States';
update schools set admission_info = $q${"ug": "Send official transcripts from all schools attended. International high school documents do not need a third party evaluation. Applicants with a GPA above 3.4 may be able to skip SAT/ACT, but this is not guaranteed.", "english": "Accepted: TOEFL iBT 69, IELTS Academic 6, SAT Reading 480, ACT English 17, Michigan English Test or PTE Academic. Duolingo is not accepted. Letters of English proficiency from non-US schools are not accepted.", "how_to_apply": "Apply through Georgia State admissions as an international first-year student. Documents must come from an official school email address or be verifiable through the exam board. Students without enough English may be considered for conditional admission through an Intensive English Program.", "deadlines": "Specific dates are not listed on the page. An application is valid for three terms of entry.", "application_fee": "The page says a fee is required but does not give the amount.", "documents": "Official transcripts from all prior schools. WAEC or NECO results checked through the exam board online checker, plus Year 9 to 12 transcripts (listed on the page under Caribbean applicants). A credential evaluation is needed only for college or university work done outside the US.", "fees_link": "https://admissions.gsu.edu/bachelors-degree/knowledgebase/international-admissions/", "sources": ["https://admissions.gsu.edu/bachelors-degree/knowledgebase/international-admissions/"]}$q$::jsonb, admission_link = $q$https://admissions.gsu.edu/bachelors-degree/knowledgebase/international-admissions/$q$, admission_checked = '2026-11-13' where id = '0b3b97f8-2c43-49f7-807d-ead68d8a51c1' and country = 'United States';
update schools set admission_info = $q${"ug": "You must have finished, or be about to finish, secondary school. IU Indianapolis looks for about a B average with strong math and science grades. SAT or ACT is not required for admission but is needed for most scholarships.", "english": "Undergraduate minimums: TOEFL iBT 60 (old scale), IELTS 5.5, Duolingo 90 (Fall 2026) or 95 (from Spring 2027), SAT Reading and Writing 410, ACT English 17. GCSE or O Level English at C is also accepted. Scores must be under 2 years old.", "how_to_apply": "The undergraduate page sends international applicants to the Office of International Affairs for the online application and steps. Confirm details there.", "fees_link": "https://indianapolis.iu.edu/admissions/apply/steps-to-apply.html", "sources": ["https://bulletins.iu.edu/iuin/2025-2026/undergraduate/admission/international.shtml", "https://indy.iu.edu/admissions/apply/undergraduate-english.html"]}$q$::jsonb, admission_link = $q$https://indianapolis.iu.edu/admissions/apply/steps-to-apply.html$q$, admission_checked = '2026-11-13' where id = '79a313fd-dfcd-4ec0-b516-682d6a938b30' and country = 'United States';
update schools set admission_info = $q${"ug": "Complete a secondary program like US high school and reach a GPA equal to 2.5 on a 4.0 scale. Official records must come directly from the issuing school, with translations.", "english": "Undergraduate applicants whose first language is not English must show at least CEFR level B2. Some applicants may be exempt at the discretion of the Office of International Services. Exact test scores were not confirmed.", "how_to_apply": "Complete the International Student Application and pay the fee. After admission, submit the Statement of Financial Support through the ISSS portal.", "application_fee": "A non-refundable fee is required. The amount was not given on the page.", "documents": "Proof of degrees, diplomas, certificates or transcripts in the original language with translations. Official copies must arrive before class registration. Proof of funds for the first year.", "fees_link": "https://MissouriState.edu/Policy/Chapter5/Op5_09_1_InternationalUndergraduateStudents.htm", "sources": ["https://MissouriState.edu/Policy/Chapter5/Op5_09_1_InternationalUndergraduateStudents.htm", "https://www.missouristate.edu/policy/Op5_08_22_Scholarships_for_International_Students.htm"]}$q$::jsonb, admission_link = $q$https://MissouriState.edu/Policy/Chapter5/Op5_09_1_InternationalUndergraduateStudents.htm$q$, admission_checked = '2026-11-13' where id = '566d7af5-3d3f-4b26-9047-14b687930eba' and country = 'United States';
update schools set admission_info = $q${"ug": "Unofficial scanned transcripts are accepted to apply. Official transcripts are needed before you register for classes. Rowan evaluates foreign credentials for free, so you do not need an outside evaluation.", "pg": "Graduate assistantships with tuition remission and a stipend are available. Applicants to thesis or PhD programs are automatically considered for research assistantships.", "english": "Proof of English is required. An SAT score of 900 or higher, or an ACT of 16 or higher, can waive the English test. Rowan offers conditional admission for students who need more English.", "how_to_apply": "Apply and track your status in the applicant portal. Official paper transcripts can be mailed to the Office of International Admissions, 225 Rowan Blvd, Glassboro, NJ 08028.", "application_fee": "$45 for undergraduate (freshman and transfer) and $65 for non-thesis graduate programs. Thesis and PhD applicants pay no fee. No fee waivers for international applicants. Admitted students pay a $100 deposit before the I-20.", "documents": "Transcripts, plus a provisional or bonafide certificate if your degree is not finished. SAT or ACT scores are optional.", "fees_link": "https://sites.rowan.edu/international/admissions/faq-in-admissions.html", "sources": ["https://sites.rowan.edu/international/admissions/faq-in-admissions.html", "https://admissions.rowan.edu/admissions-process/international-requirements/english-language-requirements.html"]}$q$::jsonb, admission_link = $q$https://sites.rowan.edu/international/admissions/faq-in-admissions.html$q$, admission_checked = '2026-11-13' where id = 'bc6ebcf4-9f97-4213-8ad1-3cf525f0ca41' and country = 'United States';
update schools set admission_info = $q${"ug": "A high school diploma or secondary certificate with at least a 3.0 on a 4.0 scale (about a B average) or equivalent. Send official records from all secondary schools, usually years 9 to 12. Exam results must be in the original language on the official form.", "pg": "Graduate Pathway: a four-year bachelor's degree with at least a 2.5 GPA or equivalent, and TOEFL iBT 70 or equivalent. Applicants without the English score can start with Academic English.", "english": "TOEFL, IELTS or accepted alternatives such as IGCSE, SAT, ACT or AP. African applicants from English-medium countries may ask for a waiver, decided case by case.", "how_to_apply": "Apply online through the international application. Email scanned documents for speed, and mail official transcripts to the Office of International Admissions in Corvallis. After the offer, sign it and pay the deposit to receive your I-20.", "deadlines": "OSU recommends applying 4 to 6 months before the start term, and at least 8 weeks before at the very least. Fixed dates were not listed for international applicants.", "documents": "Transcripts, diplomas, English scores, passport copy, bank or sponsor letter showing one year of funds, Affidavit of Support, and a health history form with proof of immunization.", "fees_link": "https://admissions.oregonstate.edu/international/applying/how-when-apply/application-checklist", "sources": ["https://catalog.oregonstate.edu/admission/international-admissions/", "https://admissions.oregonstate.edu/international/applying/how-when-apply", "https://admissions.oregonstate.edu/international/applying/how-when-apply/application-checklist"]}$q$::jsonb, admission_link = $q$https://catalog.oregonstate.edu/admission/international-admissions/$q$, admission_checked = '2026-11-13' where id = 'd485275a-649b-48c3-bb1f-e352c3ecbd97' and country = 'United States';
update schools set admission_info = $q${"ug": "International students applying to OSU-Cascades work with the international admissions office on the Corvallis campus. The Oregon State international undergraduate rule is a 3.0 GPA (about a B average) or equivalent, with official records from all secondary schools.", "english": "Oregon State accepts TOEFL, IELTS or alternatives such as IGCSE, SAT, ACT or AP. African applicants from English-medium countries may ask for a case-by-case waiver.", "how_to_apply": "International applicants apply through the Oregon State Office of International Admissions in Corvallis (admissions.oregonstate.edu/international). General questions: 541-322-3100.", "deadlines": "Oregon State recommends applying 4 to 6 months before the start term.", "documents": "Official records from all secondary schools, English scores, passport copy, and proof of funds for visa purposes.", "fees_link": "https://osucascades.edu/international-students", "sources": ["https://osucascades.edu/international-students", "https://catalog.oregonstate.edu/admission/international-admissions/"]}$q$::jsonb, admission_link = $q$https://osucascades.edu/international-students$q$, admission_checked = '2026-11-13' where id = 'bf006baf-506c-447b-af4a-93bd6bb66adb' and country = 'United States';
